CREATE OR REPLACE FUNCTION public.dtt_identity_collection_ready() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.app_settings WHERE key='dtt_identity_collection' AND value @> '{"enabled":true,"retention_reviewed":true}'::jsonb); $$;
REVOKE ALL ON FUNCTION public.dtt_identity_collection_ready() FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.dtt_identity_collection_ready() TO authenticated,service_role;
CREATE FUNCTION public.guard_dtt_identity_collection() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.dtt_identity_collection_ready() THEN RAISE EXCEPTION 'New identity collection is paused pending privacy readiness'; END IF; RETURN NEW; END $$;
CREATE TRIGGER dtt_identity_collection_gate BEFORE INSERT ON public.dtt_identity_reviews FOR EACH ROW EXECUTE FUNCTION public.guard_dtt_identity_collection();
CREATE POLICY "Identity collection readiness" ON storage.objects AS RESTRICTIVE FOR INSERT TO authenticated WITH CHECK(bucket_id NOT IN ('dtt-identity-review','creator-2257-records','identity-documents','id-verifications') OR (public.dtt_identity_collection_ready() AND split_part(name,'/',1)=auth.uid()::text));
CREATE POLICY "Never replace identity evidence" ON storage.objects AS RESTRICTIVE FOR UPDATE TO authenticated USING(bucket_id NOT IN ('dtt-identity-review','creator-2257-records','identity-documents','id-verifications')) WITH CHECK(bucket_id NOT IN ('dtt-identity-review','creator-2257-records','identity-documents','id-verifications'));
CREATE FUNCTION public.dtt_evidence_referenced(_bucket text,_path text) RETURNS boolean LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NOT NULL AND split_part(_path,'/',1)<>auth.uid()::text AND NOT public.has_role(auth.uid(),'admin') THEN RAISE EXCEPTION 'Private evidence access denied'; END IF; RETURN EXISTS(SELECT 1 FROM public.dtt_identity_reviews WHERE (document_bucket=_bucket AND _path IN(id_front_path,id_back_path,selfie_path)) OR (_bucket='dtt-identity-review' AND face_video_path=_path)); END $$;
REVOKE ALL ON FUNCTION public.dtt_evidence_referenced(text,text) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.dtt_evidence_referenced(text,text) TO authenticated,service_role;
CREATE OR REPLACE FUNCTION public.dtt_review_evidence_referenced(_path text) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.dtt_evidence_referenced('dtt-identity-review',_path); $$;
CREATE POLICY "Retain referenced DTT evidence" ON storage.objects AS RESTRICTIVE FOR DELETE TO authenticated USING(bucket_id NOT IN ('dtt-identity-review','creator-2257-records','identity-documents','id-verifications') OR (split_part(name,'/',1)=auth.uid()::text AND NOT public.dtt_evidence_referenced(bucket_id,name) AND (bucket_id='dtt-identity-review' OR NOT public.identity_evidence_is_referenced(bucket_id,name))));
CREATE POLICY "Audited administrator identity file access" ON storage.objects AS RESTRICTIVE FOR SELECT TO authenticated USING(bucket_id NOT IN ('dtt-identity-review','creator-2257-records','identity-documents','id-verifications') OR split_part(name,'/',1)=auth.uid()::text);
CREATE OR REPLACE FUNCTION public.keep_dtt_identity_evidence() RETURNS trigger LANGUAGE plpgsql SET search_path=public AS $$ BEGIN
IF (to_jsonb(NEW)-ARRAY['status','reviewed_at','reviewer_id','reviewer_notes','identity_confirmed','face_confirmed','creator_verification_id']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['status','reviewed_at','reviewer_id','reviewer_notes','identity_confirmed','face_confirmed','creator_verification_id']) THEN RAISE EXCEPTION 'Submitted identity evidence is immutable'; END IF;
IF NEW.creator_verification_id IS DISTINCT FROM OLD.creator_verification_id AND (OLD.creator_verification_id IS NOT NULL OR NEW.audience<>'creator' OR NEW.creator_verification_id IS NULL OR NOT EXISTS(SELECT 1 FROM public.creator_verifications v WHERE v.id=NEW.creator_verification_id AND v.user_id=NEW.user_id AND v.document_bucket=NEW.document_bucket AND v.id_front_path=NEW.id_front_path AND v.id_back_path=NEW.id_back_path AND v.selfie_path=NEW.selfie_path)) THEN RAISE EXCEPTION 'Creator evidence association is immutable'; END IF; RETURN NEW; END $$;
CREATE FUNCTION public.validate_dtt_identity_approval() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN
IF NEW.status='approved' THEN
IF NOT NEW.identity_confirmed OR NOT NEW.face_confirmed OR NEW.reviewer_id IS NULL OR NEW.reviewed_at IS NULL OR NOT public.has_role(NEW.reviewer_id,'admin') OR NEW.date_of_birth>(current_date-interval '18 years')::date OR NEW.document_expires_on<current_date OR EXISTS(SELECT 1 FROM public.account_bans WHERE user_id=NEW.user_id) THEN RAISE EXCEPTION 'Valid human adult review required'; END IF;
IF NEW.document_bucket<>(CASE WHEN NEW.audience='creator' THEN 'creator-2257-records' ELSE 'dtt-identity-review' END) OR (NEW.audience='creator' AND NEW.creator_verification_id IS NULL) THEN RAISE EXCEPTION 'Valid audience evidence required'; END IF;
IF (SELECT count(*) FROM storage.objects WHERE bucket_id=NEW.document_bucket AND name IN(NEW.id_front_path,NEW.id_back_path,NEW.selfie_path) AND split_part(name,'/',1)=NEW.user_id::text AND owner_id=NEW.user_id::text AND lower(metadata->>'mimetype') IN('image/jpeg','image/png','image/webp') AND (metadata->>'size')::bigint BETWEEN 1 AND 10485760)<>3 OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='dtt-identity-review' AND name=NEW.face_video_path AND split_part(name,'/',1)=NEW.user_id::text AND owner_id=NEW.user_id::text AND lower(metadata->>'mimetype') IN('video/webm','video/mp4') AND (metadata->>'size')::bigint BETWEEN 1 AND 10485760) THEN RAISE EXCEPTION 'Stored identity and face evidence required'; END IF;
END IF; RETURN NEW; END $$;
CREATE TRIGGER dtt_identity_approval_evidence BEFORE INSERT OR UPDATE ON public.dtt_identity_reviews FOR EACH ROW EXECUTE FUNCTION public.validate_dtt_identity_approval();
REVOKE ALL ON FUNCTION public.keep_dtt_identity_evidence(),public.guard_dtt_identity_collection(),public.validate_dtt_identity_approval() FROM PUBLIC,anon,authenticated;
COMMENT ON FUNCTION public.dtt_identity_collection_ready() IS 'Fail closed until the owner confirms legally reviewed retention and operational readiness in the protected dtt_identity_collection setting. No retention duration is invented; existing evidence is preserved.';